        <pattern id="heatherWeave" width="4" height="4" patternUnits="userSpaceOnUse">
          <path d="M0 2 L4 2 M2 0 L2 4" stroke="#CBD5E1" stroke-width="0.75" opacity="0.4"/>
        </pattern>
